# Quote the actual rows of every simulation results table for the scalar-pattern audit.
def sim_group_quotes(names):
 result=[]
 for page,width,ordinal in [(9,2,0),(9,2,1),(10,2,0),(11,2,0),(11,4,0),(13,2,0),(13,4,0)]:
  num=r'[0-9]+\.[0-9]{6}'
  pat=r'\s+'.join(re.escape(name)+r'\s+'+r'\s+'.join([num]*width) for name in names)
  matches=list(re.finditer(pat,textpages['00561'][page]))
  assert len(matches)>ordinal,(page,width,ordinal,names)
  result.append((page,matches[ordinal].group()))
 return result
