# Verify each PDF quotation against the extracted text and each review excerpt against an input.
errors=[]
for e in entries:
 matches=[]
 for name,src in sources:
  n=src.find(e['claim'])
  if n>=0: matches.append(f'{name}:{src.count(chr(10),0,n)+1}')
 e['sources']=matches
 if not matches:errors.append(f"{e['id']} INPUT_EXCERPT_NOT_FOUND {e['claim']}")
 for page,quote in e['anchors']:
  text=textpages[e['pid']].get(page,'')
  if quote not in text:errors.append(f"{e['id']} PDF_QUOTE_NOT_FOUND p{page}: {quote}")
  if len(quote.split())>25: errors.append(f"{e['id']} QUOTE_OVER_25_WORDS {len(quote.split())}")
print('entries',len(entries),'errors',len(errors))
for error in errors: print(error)
if errors: raise SystemExit(2)

